    "instructor": "Doç. Dr. Özge Süfer ozgesufer@hotmail.com.tr",
    "purpose": "Ambalajlamada gıda maddesinin yapısı ve ambalaj malzemesinin özellikleri önemlidir. Gıda maddesine uygun ambalaj seçimi, gıdanın sağlıklı olarak, üretiminden tüketimine kadar geçen süreci belirler. Bu dersin amacı, bu konuda öğrencinin bilgilendirilmesidir.",
    "content": "Çeşitli gıda maddelerinin ambalajlanmasında kullanılan ambalaj materyallerinin özellikleri ve ambalajlama teknikleri, çeşitli gıda maddelerinin depolanması, depolamaÜ koşulları, depolama sırasında dikkat edilecek hususlar, depolama sırasında gıda maddelerinde meydana gelen değişimler konusunda bilgiler verilmektedir.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: ÜÇÜNCÜ ,M. 2007. Gıda Ambalajlama Teknolojisi. Ege Üniversitesi İzmir.DAĞLIOĞLU, O. Gıda Ambalajlama ve Depolama Teknikleri Ders Notları (Basılmamış) NKÜ Ziraat Fakültesi Tekirdağ; Ders Notları: KELEŞ ,F. Gıda Ambalajlama İlkeleri Atatürk Üniversitesi Ziraat Fakültesi Ofset Tesisi Erzurum 2002; Sınavlar: Bölüm İnternet Adresi Üzerinde Duyurulacaktır",
