    "purpose": "Bu ders ile öğrencilere; mevzuat ve Türk Gıda Kodeksine uygun olarak tahılürünleri üretimini kontrol etme yeterliklerinin kazandırılması amaçlanmaktadır.",
    "content": "Tahılların önemi, tahıl tanelerinin yapısı, tahılların depolanması, buğday ve diğer tahıllarda kalite takdiri ve standardizasyon, un değirmenciliği, ekmek, makarna, bulgur, tarhana, bisküvi, kek, kraker, nişasta, dekstrin, glikoz, kahvaltılık tahıllar, fermente ve geleneksel tahıl ürünleri yapım teknolojileri, buğday haricindeki diğer tahılların değerlendirilmesi, tahıllar ve tahıl ürünlerinde yapılan başlıca analizler, tahıllarda ve tahıl bazlı ürünlerde kalite kontrol, bazı tahılların ve tahıl ürünlerinin standartları.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: Altan,A. (1993), Tahıl işleme Teknolojisi, Ç.Ü. Basımevi, Adana. Elgün,A., Ertugay, Z. (1995), Tahıl İşleme Teknolojisi. Atatürk Üniv.Basımevi, ErzurumTalay, M., 1997. Ekmek Bilimi ve Teknolojisi. Ray Filmcilik Matbaacılık, İstanbul, 120s.Hoseney, R. C. (2010). Principles of cereal science and technology. St. Paul, MN: AACCI.; Ders Notları: Altan,A. (1993), Tahıl işleme Teknolojisi, Çukurova Üniversitesi Basımevi, Adana.Elgün,A., Ertugay, Z. (1995), Tahıl İşleme Teknolojisi. Atatürk Üniv.Basımevi, ErzurumTalay, M., 1997. Ekmek Bilimi ve Teknolojisi. Ray Filmcilik Matbaacılık,İstanbul, 120s.",
    "sdgs": [
      "2",
      "9",
      "12"
    ],
    "outcomes": [
      "Tahıl ve tahıl ürünleri teknolojisi kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Gıda ürünleri ve proses teknolojileri alanındaki uygulamaları karşılaştırır.",
      "Tahıl ve tahıl ürünleri teknolojisi için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Tahıl ve tahıl ürünleri teknolojisi faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Tahıl ve tahıl ürünleri teknolojisi bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Tahıl teknolojisi. Tahıl çeşitleri",
      "Buğdayın anatomisi",
      "Buğdayın kimyasal bileşimi",
      "Buğdayın oluşumu",
      "Buğdayda teknik değer ölçüleri",
      "Fiziksel kimyasal ve teknolojik değerler",
      "Tahılların saklanması",
      "Depolama şartları ve depolamayı etkileyen faktörler",
      "Değirmencilik",
      "Buğdayın temizlenmesi",
      "Sözlü anlatım uygulaması Yaş ve kuru temizleme yöntemleri.",
      "Buğdayın öğütülmesi, değirmenler, elekler",
      "İrmik temizleme makineleri Unların bileşim ve özellikleri",
      "Dersin genel değerlendirmesinin yapılması, sorular-cevaplar",
      "Tahıl ve tahıl ürünleri teknolojisi: kapsam ve temel kavramlar"
    ],
