      "Arpa, Yulaf ve Çavdarda Temel Kalite Analizleri",
      "Hububat İşlemede Sanitasyon Prensipleri Ve Mikrobiyal Kontrol",
      "Tahıl ve Ürünlerinin Analizlerinde Dikkat edilecek hususlar",
      "Dersin Genel Değerlendirmesi",
