    "name": "YENİ ÜRÜN GELİŞTİRME YÖNTEMELRİ",
    "department": "Gıda Mühendisliği ABD",
    "programName": "Gıda Mühendisliği",
    "language": "Türkçe",
    "level": "Tezli Yüksek Lisans",
    "teachingMode": "Yüz Yüze",
    "theory": 3,
    "practice": 0,
    "credit": 3,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Dr. Öğr. Üyesi Kurban YAŞAR kurbanyasar@osmaniye.edu.tr",
    "purpose": "Bu ders, gıda sektöründe yeni ürün geliştirme süreçlerini çağdaş bilimsel yaklaşımlar, teknolojik yenilikler ve yaratıcı düşünme perspektifiyle ele almayı amaçlamaktadır. Günümüzde bitki bazlı ürünler, alternatif protein kaynakları, kültür eti ve fonksiyonel gıdalar gibi hızla yükselen eğilimler ile değişen tüketici beklentileri, gıda işletmelerinin sürekli olarak Ar-Ge ve inovasyon faaliyetlerine yönelmesini gerekli kılmaktadır. Bu kapsamda ders, öğrencilerin yeni ürün geliştirme sürecinin tüm aşamalarını—pazar araştırması, fikir üretimi, ürün ve formülasyon tasarımı, proses ve teknoloji geliştirme, duyusal testler ve ürünün ticarileştirilmesi—bütüncül bir bakış açısıyla öğrenmelerini hedeflemektedir.",
    "content": "Bu ders, gıda endüstrisinde yeni ürün geliştirme süreçlerini bütüncül bir yaklaşımla ele almaktadır. Ders kapsamında; küresel gıda trendleri, tüketici davranışları, pazar analizi ve rekabet değerlendirmesi incelenmektedir. Ürün fikirlerinin oluşturulması, inovasyon stratejileri, ürün tasarımı ve formülasyon geliştirme teknikleri üzerinde durulmaktadır. Bitki bazlı ürünler, alternatif proteinler, kültür eti, fonksiyonel gıdalar ve temiz etiket uygulamaları gibi güncel yaklaşımlar detaylı şekilde değerlendirilir. Ayrıca proses geliştirme, pilot üretim, kalite kontrol kriterleri, duyusal değerlendirme yöntemleri ve raf ömrü analizi dersin önemli bileşenlerindendir. Son bölümde öğrencilerin ürün prototipi hazırlaması, duyusal analiz yapması ve ticarileştirme stratejileri geliştirmesi beklenmektedir.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: Asioli, D., Aschemann-Witzel, J., & Grunert, K. G. (2020). Clean label trends in the food industry: Consumer perspectives and market strategies. Trends in Food Science & Technology, 103, 179–186.; Ders Notları: Brody, A. L., & Lord, J. B. (2007). Developing new food products for a changing marketplace (2nd ed.). CRC Press.",
    "sdgs": [
      "2",
      "3",
      "12"
    ],
    "outcomes": [
      "Yeni ürün geliştirme yöntemelri kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Gıda kalite, güvenlik ve ürün geliştirme alanındaki uygulamaları karşılaştırır.",
      "Yeni ürün geliştirme yöntemelri için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Yeni ürün geliştirme yöntemelri faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Yeni ürün geliştirme yöntemelri bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Gıda sektöründe yeni ürün geliştirmeye giriş; kavramlar ve temel ilkeler",
      "Küresel gıda trendleri ve tüketici davranışlarının analizi",
      "Pazar araştırması, hedef kitle belirleme ve rekabet değerlendirmesi",
      "Fikir geliştirme teknikleri ve inovasyon stratejileri",
      "Ürün tasarımı, fonksiyonel özellikler ve gıda bileşenlerinin rolü",
      "Formülasyon geliştirme; bitki bazlı ve alternatif proteinli ürün örnekleri",
      "Proses geliştirme, teknoloji seçimi ve pilot üretim planlaması",
      "Prototip oluşturma, ön testler ve iyileştirme çalışmaları",
      "Duyusal analiz yöntemleri ve tüketici testleri",
      "Raf ömrü değerlendirme, kalite kontrol kriterleri ve mevzuat",
      "Ticarileştirme süreci: ölçek büyütme, maliyet analizi ve ambalaj tasarımı",
      "Pazara giriş stratejileri, markalaşma ve ürün konumlandırma",
      "Başarılı ve başarısız yeni ürün örneklerinin analizi",
      "Yeni ürün geliştirme yöntemelri: kapsam ve temel kavramlar",
      "Gıda mevzuatı ve standartlar"
    ],
