      "Kımız üretim teknoloji",
      "Diğer Fermente Süt Ürünleri",
      "Fermente süt ürünleri teknolojisi: kapsam ve temel kavramlar",
      "Mikrobiyal sistemlerin özellikleri",
      "Gıda mikrobiyotasının gelişimi"
