    "content": "Monosakkarit, oligosakkarit ve polisakkaritlerin yapıları ve fonksiyonları dahil olmak üzere gıda sistemindeki karbonhidratların temelleri, ve polisakkaritler ve özellikle nişasta alanındaki son gelişmelerden oluşmaktadır.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: Horton, D., Advances in Carbonhydrate Chemistry and Biochemistry,1970; Ders Notları: 1. Saldamlı İ., Gıda Kimyası, 1998, Ankara2. Horton, D., Advances in Carbonhydrate Chemistry andBiochemistry,1970",
