    "purpose": "Bu ders, beslenme biliminin temel ilkelerini ileri düzeyde öğretmeyi; besin öğelerinin metabolizması, beslenme-sağlık ilişkisi ve güncel beslenme yaklaşımlarını bilimsel temelde değerlendirebilecek bilgi ve beceriyi kazandırmayı amaçlar.",
    "content": "Beslenme rehberi ve beslenmedeki bileşenler, besin maddelerinin sindirimi, emilimi ve metabolizması, enerji tüketimi ve vücut ağırlığının korunmasında besin maddelerinin etkilerinden oluşmaktadır.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: Berdanier, C. D., Dwyer, J. T., & Feldman, E. B. (Eds.). (2007). Handbook of nutrition and food. CRC press.; Ders Notları: Denise R. Ferrier, Biochemistry; Prof. Dr. Ayşe Baysal, Beslenme",
