    "content": "Denemelerin Planlanması, Uygulanması, Yürütülmesi, Değerlendirilmesi ve Yorumu; Deneme Düzen ve Desenleri. Tekerrürsüz Denemeler, Temel İstatistik tanımlar ve testler, İnteraksiyonların yorumlanması, Ortoganal karşılaştırmalar, Tek Faktörlü Denemeler, Matematik Modelleri ile Deneme Desenleri, Eksik Parseller, İki Faktörlü Denemeler, Üç Faktörlü Denemeler, Üç Faktörlü Deneme Düzenleri. Çeşit Nitelikli Seviyelerin Karşılaştırılması, Doz Nitelikli Seviyelerin Ortogonal Karşılaştırılması",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: RENCHER, A.C., 2002. Methods of Multivariate Analysis, John Wiley and Sons Ltd., 708p; Ders Notları: RENCHER, A.C., 2002. Methods of Multivariate Analysis, John Wiley andSons Ltd., 708p.ÖZDAMAR, K., 1999. Paket Programlar ile İstatistiksel Veri Analizi,Kaan Kitabevi, Eskişehir, 535s.",
