    "content": "Reolojinin tanımı ve tarihi; reoloji ve tekstür farkı; kesme ve kuvvet tanımları; Reolojik davranış modelleri; Newtonian ve Newtonian olmayan akışkanlar; Zamana bağlı (reopektik; tiksotropik) ve zamana bağlı olmayan (pseudoplastik ve dilatant) akışkanlar",
