    "content": "Giriş, İmmobilizasyon yöntemleri, İmmobilizasyonun hücre fizyolojisi ve fermentasyon üzerine etkisi, Kullanılan reaktörler, İmmobilize hücrelerin gıda sanayiinde kullanımı.",
