    "content": "Dondurmanın besin değeri, dondurma yapımında kullanılan ham maddeler, dondurma üretim şeması, dondurma miskinin hazırlanması ve hesaplanması, dondurma çeşitleri, dondurmalarda görülen bozukluklar ve sebepleri",
