    "programName": "Gıda Mühendisliği",
    "language": "Türkçe",
    "level": "Tezli Yüksek Lisans",
    "teachingMode": "Yüz Yüze",
    "theory": 3,
    "practice": 0,
    "credit": 3,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Doç. Dr. Meriç Şimşek Aslanoğlu",
    "purpose": "Canlılığın temelini oluşturan enzimlerin yapıları, çeşitleri, etki mekanizmaları ve inhibisyonlarının temel prensiplerini öğretmektir. Kantitatif özelliğe sahip olan enzim çalışma mekanizmalarının rakamsal örneklerle açıklanmasıdır.",
    "content": "Enzim yapıları ve enzimlerin çalışma prensibi/Enzim etki mekanizmaları ve enzimlerin kimyasal katalizörlerle olan farkları/Enzim etki mekanizmaları/Enzim kinetiği/Km değerinin önemi ve rakamsal olarak hesaplanması/Inhibisyon tiplerinin bulunması",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, örnek olay çözümlemesi, uygulama verilerinin değerlendirilmesi ve akademik tartışma.",
    "resources": "Kaynaklar: 123; Ders Notları: Irwin H. Segel, Behavior and Analysis of Rapid Equilibrium and Steady-State Enzyme Systems",
    "sdgs": [
      "2",
      "3",
      "9"
    ],
    "outcomes": [
      "Enzim kinetiği kapsamındaki temel ve ileri yaklaşımları analiz eder.",
      "Gıda mikrobiyolojisi ve biyoteknolojisi alanındaki uygulamaları karşılaştırır.",
      "Enzim kinetiği için sürdürülebilir bir uygulama yaklaşımı geliştirir.",
      "Enzim kinetiği faaliyetlerindeki etkileri ve riskleri değerlendirir.",
      "Enzim kinetiği bulgularını etik ve bilimsel ölçütlerle yorumlar."
    ],
    "weeklyTopics": [
      "Enzim yapıları ve enzimlerin çalışma prensipleri",
      "Enzim çeşitleri ve kofaktörlerin fonksiyonları",
      "Enzim etki mekanizmaları ve enzimlerin kimyasal katalizörlerle olan farkları",
      "Esnek enzim induced fit hipotezi",
      "Enzimlerin katalitik veriminden sorumlu faktörler",
      "Enzim kinetiği",
      "Km değerinin önemi ve kullanımı",
      "Km değeri ile ilgili uygulamalar",
      "Reaksiyon sıraları",
      "Eğriler kullanılarak Km değerlerinin hesaplanması",
      "Inhibitörler, inhibasyon çeşitleri ve inhibitör tiplerinin bulunması",
      "Çok bölgeli ve allosterik enzimler",
      "Çok substratlı enzimler ve kinetik mekanizmaları",
      "Enzim kinetiği: kapsam ve temel kavramlar",
      "Mikrobiyal sistemlerin özellikleri"
    ],
